"""mangui guides, batch 7: ffuf, hydra, sqlmap, steghide.
Examples teach (command + explanation); nothing is captured. Written by scripts/mangui_write.py.
Use these tools only on systems you own or are explicitly authorised to test (CTF targets, your lab)."""

GUIDES = []

# ============================================================== ffuf
GUIDES.append(dict(
    name="ffuf", section="1", one_line="fast web fuzzer",
    plain=["`ffuf` replaces the word FUZZ in a request with every line of a wordlist and shows which answers look interesting. FUZZ can sit in the path, a parameter, a header, a cookie or a POST body.",
           "That one idea covers directory discovery, parameter discovery, virtual host discovery and simple login guessing. The skill is in filtering: most guesses give the same boring reply, so you hide it by status (-fc), size (-fs), words (-fw) or lines (-fl) and look at what is left."],
    when=["Find hidden paths and files.", "Find unknown GET/POST parameters.", "Find virtual hosts by changing the Host header.", "Test many values in a field with a filter on the response."],
    examples=[("Directory discovery", "ffuf -u http://10.10.10.5/FUZZ -w /usr/share/wordlists/dirb/common.txt", "FUZZ in the URL is replaced with each word. Results print with status, size, words and lines."),
              ("Hide the common reply", "ffuf -u http://10.10.10.5/FUZZ -w common.txt -fc 404 -fs 1234", "-fc hides a status code and -fs hides a response size. If every wrong guess is 1234 bytes, hiding that size leaves only the real hits."),
              ("Add extensions", "ffuf -u http://10.10.10.5/FUZZ -w common.txt -e .php,.txt,.bak", "-e tries each word with each extension too."),
              ("Find virtual hosts", "ffuf -u http://10.10.10.5/ -H 'Host: FUZZ.target.htb' -w subdomains.txt -fs 4242", "FUZZ goes in the Host header. A different size from the default means a different site."),
              ("Fuzz a parameter name", "ffuf -u 'http://10.10.10.5/page.php?FUZZ=1' -w params.txt -fs 0", "Finds which parameter changes the page; many hidden pages react to ?debug= or ?file=."),
              ("Fuzz a parameter value", "ffuf -u 'http://10.10.10.5/page.php?id=FUZZ' -w <(seq 1 200) -fc 404", "A numbered list of ids shows which exist. Process substitution <(seq 1 200) builds the list on the fly."),
              ("POST login guessing in a lab", "ffuf -u http://10.10.10.5/login -X POST -d 'user=admin&pass=FUZZ' -H 'Content-Type: application/x-www-form-urlencoded' -w passwords.txt -fr 'Invalid'", "-fr hides replies matching a regular expression (here the failure message). The reply that is different is the match."),
              ("Two wordlists at once", "ffuf -u http://10.10.10.5/W1/W2 -w dirs.txt:W1 -w files.txt:W2", "Name each list with :NAME and use that name in the request to try all combinations."),
              ("Save as a file", "ffuf -u http://10.10.10.5/FUZZ -w common.txt -o out.json -of json", "-o and -of write results as json, csv, html and more.")],
    options=[
        ("-u URL", "Target URL, with FUZZ marking the spot.", "Always."),
        ("-w FILE[:KEYWORD]", "Wordlist, optionally with a keyword name (default FUZZ).", "Always."),
        ("-H 'Header: value'", "Add a header; can hold FUZZ.", "Vhost and token tests."),
        ("-X METHOD", "HTTP method.", "POST, PUT."),
        ("-d DATA", "Request body.", "Form or JSON fuzzing."),
        ("-b 'a=b; c=d'", "Cookie data.", "Logged-in fuzzing."),
        ("-e ext1,ext2", "Extensions added to each word.", "Files."),
        ("-mc codes", "Match these status codes (default 200-299,301,302,307,401,403,405,500).", "Only certain results."),
        ("-ms size / -mw words / -ml lines / -mr regex", "Match by size, word count, line count or regex.", "Positive matching."),
        ("-fc codes", "Filter out these status codes.", "Hiding noise."),
        ("-fs size / -fw words / -fl lines / -fr regex", "Filter out by size, word count, line count or regex.", "Hiding the common reply."),
        ("-ac", "Auto-calibrate filters.", "Quick start when unsure."),
        ("-t N", "Threads (default 40).", "Speed."),
        ("-rate N", "Requests per second.", "Staying under a limit."),
        ("-p seconds", "Delay between requests.", "Slow targets."),
        ("-timeout N", "Request timeout.", "Slow targets."),
        ("-maxtime N", "Stop after N seconds.", "Time limits."),
        ("-mode clusterbomb|pitchfork|sniper", "How multiple wordlists combine.", "Several FUZZ points."),
        ("-recursion / -recursion-depth N", "Recurse into found directories.", "Digging deeper."),
        ("-r", "Follow redirects.", "Redirected pages."),
        ("-x URL", "Use a proxy.", "Through Burp."),
        ("-replay-proxy URL", "Replay only the matched requests to a proxy.", "Inspecting hits in Burp."),
        ("-k", "Skip TLS verification.", "Self-signed lab sites."),
        ("-o FILE / -of FORMAT", "Output file and format.", "Saving results."),
        ("-c", "Colourise output.", "Readability."),
        ("-s", "Silent mode.", "Scripts."),
        ("-v", "Verbose: print full URL and redirect.", "Debugging."),
        ("-sf / -se", "Stop on spurious errors or on all errors.", "Safe runs."),
        ("-ic", "Ignore comment lines in the wordlist.", "Wordlists with comments."),
        ("-input-cmd CMD", "Run a command to produce the input.", "Generated lists."),
        ("-h", "Help.", "A reminder.")],
    mistakes=["Not filtering: a thousand lines of the same reply hide the one that matters. Try -ac or -fs.", "Forgetting to quote a URL with & or ? in the shell.", "Wrong keyword when you use two lists.", "Too many threads on a small server.", "Fuzzing a real site without permission."],
    try_=["Find a hidden directory with common.txt and -fc 404.", "Find the response size of a wrong guess, then filter it with -fs.", "Try Host: FUZZ.target.htb on a lab machine."],
    see_also="gobuster(1), wfuzz(1), curl(1), burpsuite, and the seclists wordlists in /usr/share/seclists."))

# ============================================================== hydra
GUIDES.append(dict(
    name="hydra", section="1", one_line="network logon cracker (online password guessing)",
    plain=["`hydra` tries many usernames and passwords against a live service (SSH, FTP, HTTP forms, RDP, SMB, databases...) until one works. This is online guessing, so it is slow compared with cracking a hash, and it can lock accounts or trigger alarms.",
           "Use it only in labs and tests where you have written permission. It is a classic CTF tool when a service has a weak password and you have a username or a wordlist."],
    when=["Guess an SSH or FTP login in a lab.", "Test a web login form in a challenge.", "Check whether a service accepts weak or default passwords."],
    examples=[("One user, wordlist of passwords (SSH)", "hydra -l admin -P /usr/share/wordlists/rockyou.txt ssh://10.10.10.5", "-l is a single login name, -P a password list. The service and target form the last argument."),
              ("Many users, many passwords", "hydra -L users.txt -P passwords.txt ftp://10.10.10.5", "-L is a user list. Hydra tries combinations; keep lists short because online guessing is slow."),
              ("Limit threads (be gentle)", "hydra -l admin -P pass.txt -t 4 ssh://10.10.10.5", "-t sets parallel tasks. SSH servers drop many connections, so 4 is wise."),
              ("A web login form", "hydra -l admin -P pass.txt 10.10.10.5 http-post-form '/login.php:user=^USER^&pass=^PASS^:F=Invalid'", "Three parts separated by colons: the path, the body with ^USER^ and ^PASS^ as placeholders, and the failure text (F=). Hydra treats a reply without the failure text as a success."),
              ("Stop at the first success", "hydra -l admin -P pass.txt -f ssh://10.10.10.5", "-f stops after the first working login."),
              ("Try a blank, same-as-login and reversed password", "hydra -L users.txt -e nsr ssh://10.10.10.5", "-e n tries empty passwords, s tries the login as password, r tries it reversed. Cheap and often works on weak accounts."),
              ("Colon-separated list", "hydra -C creds.txt ssh://10.10.10.5", "-C reads user:password pairs, good for default credential lists.")],
    options=[
        ("-l LOGIN / -L FILE", "A single login name / a file of login names.", "Which users."),
        ("-p PASS / -P FILE", "A single password / a file of passwords.", "Which passwords."),
        ("-C FILE", "Colon separated 'login:pass' file instead of -L/-P.", "Default credential lists."),
        ("-e nsr", "Try n (null), s (same as login), r (reversed login).", "Cheap extra guesses."),
        ("-M FILE", "File of targets.", "Several hosts."),
        ("-t TASKS", "Number of parallel tasks (default 16).", "Speed and politeness."),
        ("-T TASKS", "Total tasks across all hosts.", "Large target lists."),
        ("-w TIME / -W TIME", "Wait time for replies / between connections per task.", "Slow or protected services."),
        ("-f / -F", "Stop at the first found login (per host / overall).", "Saving time."),
        ("-s PORT", "Use a non-standard port.", "SSH on 2222."),
        ("-S", "Use SSL.", "HTTPS or similar."),
        ("-4 / -6", "Force IPv4 / IPv6.", "Network choice."),
        ("-x MIN:MAX:CHARSET", "Generate passwords by brute force (e.g. 4:6:a1).", "Short unknown passwords."),
        ("-u", "Loop over users first, not passwords.", "Avoiding lock-outs."),
        ("-o FILE", "Write found logins to a file.", "Saving results."),
        ("-b FORMAT", "Output format (text, json, jsonv1).", "Scripts."),
        ("-R", "Restore an aborted session.", "Resume."),
        ("-I", "Ignore an old restore file.", "Start fresh."),
        ("-v / -V / -d", "Verbose, show each attempt, debug.", "Seeing what happens."),
        ("-q", "Do not print connection errors.", "Clean output."),
        ("-U SERVICE", "Show details about a service module.", "Learning module syntax."),
        ("-m OPTIONS", "Module options.", "Service-specific settings."),
        ("-h", "Help.", "A reminder.")],
    mistakes=["Locking real accounts: online guessing triggers lockout policies.", "Too many tasks: SSH refuses and hydra reports false failures.", "A wrong failure string in http-post-form: hydra then reports every password as valid.", "Not capturing the real request first: check the form with the browser or curl.", "Using it where you have no permission."],
    try_=["Set up a lab SSH user with a weak password and find it with a short list.", "Read the module help with hydra -U http-post-form.", "Compare -t 4 and -t 16 on a lab SSH server."],
    see_also="john(8), hashcat(1), medusa(1), ncrack(1), nmap(1), curl(1), and the wordlists in /usr/share/wordlists."))

# ============================================================== sqlmap
GUIDES.append(dict(
    name="sqlmap", section="1", one_line="automatic SQL injection and database takeover tool",
    plain=["`sqlmap` tests a web request for SQL injection and, when it finds a hole, can list databases, tables and columns and dump the data. It automates what you would otherwise do by hand with quotes and UNION SELECT.",
           "Give it a URL with a parameter (or a saved request) and it tries many injection techniques, learns the database type and shows what it can read. It only works on targets where you have permission, such as a CTF or your own lab."],
    when=["Check whether a parameter is injectable.", "List databases, tables and columns of a vulnerable lab app.", "Dump a table that holds the flag.", "Reuse a request captured in Burp."],
    examples=[("Test a URL parameter", "sqlmap -u 'http://10.10.10.5/item.php?id=1' --batch", "-u names the target; the parameter to test is the one in the query string. --batch accepts the defaults so no questions are asked."),
              ("List the databases", "sqlmap -u 'http://10.10.10.5/item.php?id=1' --dbs --batch", "--dbs asks the injected query for the names of the databases."),
              ("List tables, then dump one", "sqlmap -u 'http://10.10.10.5/item.php?id=1' -D shop --tables\nsqlmap -u 'http://10.10.10.5/item.php?id=1' -D shop -T users --dump", "-D picks a database, -T a table. --dump downloads every row. Do it in two steps so you only take what you need."),
              ("Use a saved request", "sqlmap -r request.txt --batch", "-r reads a raw HTTP request you saved from Burp, including cookies and POST body."),
              ("A POST form", "sqlmap -u http://10.10.10.5/login --data 'user=a&pass=b' -p user --batch", "--data gives the POST body and -p chooses the field to test."),
              ("Raise the level of testing", "sqlmap -u 'http://10.10.10.5/item.php?id=1' --level 3 --risk 2 --batch", "--level adds more places to test (cookies, headers); --risk adds heavier payloads. Higher is slower and noisier."),
              ("Read a file", "sqlmap -u 'http://10.10.10.5/item.php?id=1' --file-read=/etc/passwd", "Asks the database to read a file from the server, if the database user has the right. Lab targets only.")],
    options=[
        ("-u URL", "Target URL with parameters.", "A GET target."),
        ("-r FILE", "Load the HTTP request from a file.", "Complex requests."),
        ("--data=DATA", "POST body.", "Forms."),
        ("--cookie=COOKIE", "Cookie header value.", "Logged-in tests."),
        ("-H / --headers", "Extra headers.", "Tokens."),
        ("--method=METHOD", "Force the method.", "PUT and others."),
        ("-p PARAM", "Test only this parameter.", "Faster, focused."),
        ("--skip=PARAM", "Skip this parameter.", "Ignoring noise."),
        ("--level=1-5", "Depth of tests.", "Hidden injection points."),
        ("--risk=1-3", "Risk of payloads.", "Harder cases."),
        ("--technique=BEUSTQ", "Choose techniques: Boolean, Error, Union, Stacked, Time, Query.", "Restricting to what works."),
        ("--dbms=NAME", "Force the database type.", "Saving time."),
        ("--batch", "Never ask; use defaults.", "Scripts and fast runs."),
        ("--dbs", "List databases.", "First step."),
        ("--tables", "List tables.", "After picking -D."),
        ("--columns", "List columns.", "After picking -T."),
        ("--dump", "Dump table data.", "Getting the data."),
        ("--dump-all", "Dump everything.", "Noisy; use with care."),
        ("-D / -T / -C", "Choose database, table, columns.", "Focus."),
        ("--current-user / --current-db / --is-dba", "Who am I and what rights?", "Understanding access."),
        ("--passwords", "Dump database password hashes.", "Then crack with john or hashcat."),
        ("--sql-shell", "Run SQL interactively.", "Custom queries."),
        ("--os-shell", "Interactive operating-system shell if possible.", "Authorised labs only."),
        ("--file-read / --file-write / --file-dest", "Read or write files on the server.", "Labs."),
        ("--proxy=URL", "Send through a proxy.", "Inspect in Burp."),
        ("--random-agent", "Random browser user agent.", "Avoiding simple blocks."),
        ("--delay=N / --timeout=N / --retries=N", "Pacing and reliability.", "Flaky targets."),
        ("--tamper=SCRIPT", "Use a script that disguises payloads.", "Filters and WAFs."),
        ("--forms", "Test the forms on the page.", "Finding inputs automatically."),
        ("--crawl=N", "Crawl the site to this depth.", "Finding more targets."),
        ("--flush-session", "Forget earlier results.", "Starting over."),
        ("-v N", "Verbosity 0-6.", "Seeing payloads."),
        ("-h / -hh", "Basic / full help.", "A reminder.")],
    mistakes=["Running --dump-all on a big database: slow and loud. Take one table.", "Testing the wrong parameter: use -p.", "Letting --batch make choices you did not review.", "Forgetting cookies: the page then redirects to login and everything looks safe.", "Using it on systems you are not authorised to test."],
    try_=["Capture a request in Burp, save it and run sqlmap -r on a lab app.", "List databases, then tables, then dump only the users table.", "Crack any password hash you get with john."],
    see_also="burpsuite, curl(1), john(8), hashcat(1), and the OWASP SQL injection pages."))

# ============================================================== steghide
GUIDES.append(dict(
    name="steghide", section="1", one_line="hide data inside pictures and audio",
    plain=["`steghide` hides a secret file inside an ordinary JPEG, BMP, WAV or AU file, protected by a passphrase. The picture still looks normal.",
           "In CTFs you meet it as a found picture that may hold a hidden file: steghide info tells you whether something is embedded and steghide extract pulls it out when you know the passphrase.",
           "If you do not know the passphrase, try an empty one, words from the challenge, or guess it with stegseek."],
    when=["Check whether a JPEG or WAV carries hidden data.", "Extract a hidden file once you have a passphrase.", "Hide a note in a picture to understand the technique."],
    examples=[("Is anything embedded?", "steghide info photo.jpg", "Asks for a passphrase (press Enter for none) and says whether embedded data exists, with its name and size."),
              ("Extract the hidden file", "steghide extract -sf photo.jpg", "-sf is the stego file. You are asked for the passphrase; the secret file appears in the current folder."),
              ("Extract with the passphrase given", "steghide extract -sf photo.jpg -p 'letmein' -xf out.txt", "-p supplies the passphrase and -xf chooses the name of the extracted file."),
              ("Hide a file", "steghide embed -cf cover.jpg -ef secret.txt -p 'letmein'", "-cf is the cover file (picture), -ef the file to hide. The picture is changed in place, so keep a copy of the original."),
              ("Guess passphrases from a list", "stegseek photo.jpg /usr/share/wordlists/rockyou.txt", "stegseek is a separate fast tool that tries every word as the passphrase.")],
    options=[
        ("embed, --embed", "Hide data.", "Making a stego file."),
        ("extract, --extract", "Pull hidden data out.", "Reading a stego file."),
        ("info, --info", "Show whether data is embedded and details.", "First check."),
        ("encinfo, --encinfo", "List available encryption algorithms and modes.", "Seeing the choices."),
        ("-cf, --coverfile FILE", "The cover file (the picture or sound).", "embed."),
        ("-ef, --embedfile FILE", "The file to hide.", "embed."),
        ("-sf, --stegofile FILE", "The stego file (the output of embed, input of extract).", "extract and embed."),
        ("-xf, --extractfile FILE", "Name for the extracted file.", "extract."),
        ("-e, --encryption ALGO [MODE]", "Choose encryption algorithm and mode.", "Custom settings."),
        ("-z, --compress N", "Compression level 1-9.", "Smaller embedded data."),
        ("-Z, --dontcompress", "Do not compress.", "Speed."),
        ("-K, --nochecksum", "Do not store a checksum.", "Smaller data."),
        ("-N, --dontembedname", "Do not store the file name.", "Less revealing."),
        ("-p, --passphrase PASS", "Passphrase on the command line.", "Scripts."),
        ("-f, --force", "Overwrite existing files.", "No prompts."),
        ("-q, --quiet", "Suppress information messages.", "Scripts."),
        ("-v, --verbose", "Display detailed information.", "Debugging."),
        ("-V, --version", "Show the version.", "Check install."),
        ("-h, --help", "Show help.", "A reminder.")],
    mistakes=["Giving up when the passphrase is unknown: try pressing Enter; many challenges use no passphrase.", "Expecting steghide to open PNG: it only works on JPEG, BMP, WAV and AU.", "Embedding in your only copy of a picture.", "Using steghide for LSB tricks in PNG: that needs zsteg or other tools."],
    try_=["Hide a text file in a JPEG, then run steghide info on it.", "Extract it with the passphrase.", "Run stegseek with a short wordlist on the same file."],
    see_also="exiftool(1), binwalk(1), strings(1), xxd(1), stegseek(1), zsteg(1), and file(1) to check the real type."))
